print('--- title:', re.search(r'<title>(.*?)</title>',t).group(1) if re.search(r'<title>(.*?)</title>',t) else '')
"; done

cd /tmp && python3 -c "
import re,subprocess
pages=['','about','academics','life-at-michigan','athletics','research','health-medicine','initiatives','giving','facts-figures','contact','about/privacy','schools-colleges','prospective-students','current-students','faculty-staff','parents','alumni']
s=set()
for p in pages:
    h=subprocess.run(['curl','-s','http://localhost:35963/'+p+'/'],capture_output=True,text=True).stdout
    h=re.sub(r'<script.*?</script>','',h,flags=re.S)
    for im in re.findall(r'<img[^>]*src=\"([^\"]*)\"',h):
        if im.startswith('/_images/') or im.startswith('/media/') or im.startswith('/assets_gen/') or im.startswith('/includes/'):
            s.add(im)
    # also splash/background images in style attributes
    for im in re.findall(r'url\(([^)]*)\)',h):
        im=im.strip('\'\"')
        if im.startswith('/_images/') or im.startswith('/media/') or im.startswith('/assets_gen/') or im.startswith('/includes/'):
            s.add(im)
for i in sorted(s): print(i)
" | tee /tmp/allassets.txt | wc -l
